<h2 class="mb-3">Lịch sử giao dịch</h2><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Thời gian</th><th>Tài khoản</th><th>Loại</th><th>Số tiền</th><th>Nội dung</th></tr></thead><tbody><?php foreach ($transactions as $transaction): ?><tr><td><?= htmlspecialchars((string) $transaction['created_at']) ?></td><td><?= htmlspecialchars((string) $transaction['username']) ?></td><td><?= htmlspecialchars((string) $transaction['type']) ?></td><td><?= number_format((float) $transaction['amount'], 0, ',', '.') ?> đ</td><td><?= htmlspecialchars((string) $transaction['description']) ?></td></tr><?php endforeach; ?></tbody></table></div>
